"""Enterprise DITA architecture learned-QA seeds."""

from __future__ import annotations

from typing import Any

ANSWER_STYLE = "senior_technical_docs"


def _topic(category: str) -> str:
    lowered = category.lower()
    if "cms" in lowered or "repository" in lowered:
        return "cms_architecture"
    if "processing" in lowered:
        return "processing_architecture"
    if "chatbot" in lowered:
        return "chatbot_governance"
    return "reuse_and_maps"


def _entry(
    *,
    question: str,
    short_answer: str,
    answer: str,
    category: str,
    sub_category: str,
    question_type: str,
    keywords: list[str],
    must_include: list[str],
    must_not_claim: list[str],
    behavior_scope: str,
    related_questions: list[str],
    dita_version: str = "DITA 1.2 and DITA 1.3 concepts; verification required for processor-specific behavior",
) -> dict[str, Any]:
    tags = []
    for value in [*keywords, category, sub_category, question_type, "enterprise", "dita"]:
        text = str(value or "").strip().lower().replace(" ", "_")
        if text and text not in tags:
            tags.append(text)
    include_lines = "\n".join(f"- {item}" for item in must_include)
    avoid_lines = "\n".join(f"- {item}" for item in must_not_claim)
    related_lines = "\n".join(f"- {item}" for item in related_questions[:3])
    final_answer = f"""## Short answer
{short_answer}

## Detailed answer
{answer}

## Behavior scope
{behavior_scope}

## Must cover
{include_lines}

## Must not claim
{avoid_lines}

## Verification
- DITA version: {dita_version}.
- Source fields are empty because no authoritative source URL was supplied for this curated enterprise seed.

## Related questions
{related_lines}"""
    return {
        "prompt": question,
        "topic": _topic(category),
        "tags": tags[:14],
        "answer_style": ANSWER_STYLE,
        "final_answer": final_answer.strip(),
    }


def _failure_entry(
    *,
    question: str,
    short_answer: str,
    expected_behavior: str,
    probable_cause: str,
    checks: list[str],
    keywords: list[str],
    must_not_claim: list[str],
    behavior_scope: str = "DITA specification concepts, DITA-OT implementation, CMS behavior, editor behavior, or a combination; verify against the target processor and map context.",
) -> dict[str, Any]:
    checks_text = "\n".join(f"{index}. {item}" for index, item in enumerate(checks, 1))
    avoid_text = "\n".join(f"- {item}" for item in must_not_claim)
    tags = []
    for value in [*keywords, "failure_behavior", "troubleshooting", "enterprise", "dita"]:
        text = str(value or "").strip().lower().replace(" ", "_")
        if text and text not in tags:
            tags.append(text)
    answer = f"""## Short answer
{short_answer}

## Expected behavior
{expected_behavior}

## Probable cause
{probable_cause}

## Deterministic checks
{checks_text}

## Behavior scope
{behavior_scope}

## Must not claim
{avoid_text}

## Verification
- Source fields are empty because no authoritative source URL was supplied for this curated enterprise failure seed.
- Verify with the same root map, branch, DITAVAL profile, processor version, and output target used by the failing case."""
    return {
        "prompt": question,
        "topic": _topic("DITA processing architecture" if any(term in " ".join(keywords).lower() for term in ("cache", "processor", "publishing", "html5", "native pdf")) else "DITA CMS architecture"),
        "tags": tags[:14],
        "answer_style": ANSWER_STYLE,
        "final_answer": answer.strip(),
    }


def _concept_entry(
    *,
    question: str,
    short_answer: str,
    category: str,
    sub_category: str,
    keywords: list[str],
    details: list[str],
    must_not_claim: list[str],
    behavior_scope: str = "DITA specification concepts with processor-specific validation details where URI parsing, filtering, or diagnostics are implementation-dependent.",
) -> dict[str, Any]:
    detail_text = "\n".join(f"- {item}" for item in details)
    avoid_text = "\n".join(f"- {item}" for item in must_not_claim)
    tags = []
    for value in [*keywords, category, sub_category, "conceptual", "enterprise", "dita"]:
        text = str(value or "").strip().lower().replace(" ", "_")
        if text and text not in tags:
            tags.append(text)
    final_answer = f"""## Short answer
{short_answer}

## Detailed answer
{detail_text}

## Behavior scope
{behavior_scope}

## Must not claim
{avoid_text}

## Verification
- Source fields are empty because no authoritative source URL was supplied for this curated addressing/key-resolution seed.
- Verify processor diagnostics with the exact DITA version, root map, catalog, file system, and output transform used by the project."""
    return {
        "prompt": question,
        "topic": "reuse_and_maps",
        "tags": tags[:14],
        "answer_style": ANSWER_STYLE,
        "final_answer": final_answer.strip(),
    }


